const outputDir = path.join(__dirname, '../output');
const assetsDir = path.join(outputDir, 'assets');

const jsFile = fs.readdirSync(assetsDir).find(f => f.endsWith('.js'));
const cssFile = fs.readdirSync(assetsDir).find(f => f.endsWith('.css'));

const jsContent = fs.readFileSync(path.join(assetsDir, jsFile), 'utf8');
const cssContent = fs.readFileSync(path.join(assetsDir, cssFile), 'utf8');

const htmlFiles = fs.readdirSync(outputDir).filter(f => f.endsWith('.html'));

htmlFiles.forEach(htmlFile => {
  const htmlPath = path.join(outputDir, htmlFile);
  let htmlContent = fs.readFileSync(htmlPath, 'utf8');

  // Replace script tag
  const scriptRegex = /<script\s+type="module"\s+crossorigin\s+src="[^"]+"><\/script>/;
  htmlContent = htmlContent.replace(scriptRegex, `<script>${jsContent}</script>`);

  // Replace link tag
  const linkRegex = /<link\s+rel="stylesheet"\s+crossorigin\s+href="[^"]+">/;
  htmlContent = htmlContent.replace(linkRegex, `<style>${cssContent}</style>`);

  fs.writeFileSync(htmlPath, htmlContent, 'utf8');
});

console.log('Inlining complete.');
