const fs = require('fs');
const path = require('path');

const outputDir = path.join(__dirname, '../output');
const assetsDir = path.join(outputDir, 'assets');

// Try to read assets, if they don't exist it means we already inlined? No, we didn't delete them.
let jsFile, cssFile;
try {
  jsFile = fs.readdirSync(assetsDir).find(f => f.endsWith('.js'));
  cssFile = fs.readdirSync(assetsDir).find(f => f.endsWith('.css'));
} catch (e) {
  console.log('Assets dir not found, maybe already inlined? Rebuilding...');
  process.exit(1);
}

let jsContent = fs.readFileSync(path.join(assetsDir, jsFile), 'utf8');
let cssContent = fs.readFileSync(path.join(assetsDir, cssFile), 'utf8');

// Escape </script> in JS content
jsContent = jsContent.replace(/<\/script>/g, '<\\/script>');

const htmlFiles = fs.readdirSync(outputDir).filter(f => f.endsWith('.html'));

htmlFiles.forEach(htmlFile => {
  const htmlPath = path.join(outputDir, htmlFile);
  let htmlContent = fs.readFileSync(htmlPath, 'utf8');

  // We need to use a function for the replacer so special patterns like $& are ignored
  const scriptRegex = /<script\s+type="module"\s+crossorigin\s+src="[^"]+"><\/script>/;
  htmlContent = htmlContent.replace(scriptRegex, () => `<script>${jsContent}</script>`);

  const linkRegex = /<link\s+rel="stylesheet"\s+crossorigin\s+href="[^"]+">/;
  htmlContent = htmlContent.replace(linkRegex, () => `<style>${cssContent}</style>`);

  fs.writeFileSync(htmlPath, htmlContent, 'utf8');
});

console.log('Inlining complete.');
